from tally.counter import totals
from tally.report import summary


def test_counts_by_hold():
    assert totals([{"hold": "A"}, {"hold": "A"}, {"hold": "B"}]) == {"A": 2, "B": 1}


def test_skips_missing_hold():
    assert totals([{"hold": "A"}, {}, {"hold": "B"}]) == {"A": 1, "B": 1}


def test_skips_empty_hold():
    assert totals([{"hold": "A"}, {"hold": ""}, {"hold": "B"}]) == {"A": 1, "B": 1}


def test_summary_sorted_alphabetically():
    items = [
        {"hold": "C"},
        {"hold": "A"},
        {"hold": "B"},
        {"hold": "A"},
    ]
    assert summary(items) == "A=2, B=1, C=1"
